"""Render self-contained workflows; callers never fetch helper code from a moving branch."""
from pathlib import Path
import sys
import textwrap

HERE = Path(__file__).resolve().parent
WORKFLOWS = HERE.parent / "workflows"
CHECKOUT = "3d3c42e5aac5ba805825da76410c181273ba90b1"
NODE = "949feb2413d6458794dcd2491c4babbbce0c15c1"
GO = "b7ad1dad31e06c5925ef5d2fc7ad053ef454303e"
UPLOAD = "cf430e030ddbb5b0abf93d22962f4752f3646cd9"
DOWNLOAD = "9000827ccba6bdab643e8b6fd33ac0654aef8333"
AUTH = "3268eb413133e2960fa4ae0e963ca76380c54cd9"


def step_script(name, script, extra=""):
    source = (HERE / "common.py").read_text() + "\n" + (HERE / script).read_text()
    return (f"      - name: {name}\n" + extra + "        shell: bash\n        run: |\n"
            + "          python3 - <<'PY'\n" + textwrap.indent(source, "          ") + "          PY\n")


def render(kind):
    tool_input = ""
    if kind == "npm":
        tool_input = """      node-version:
        description: Node version used to build and test; publishing uses Node 24
        type: string
        default: '24'
"""
    elif kind == "rust":
        tool_input = """      toolchain:
        description: Rust toolchain used for tests and packaging
        type: string
        default: stable
"""
    text = f"""# Generated by .github/release-tools/render.py. Edit the sources, then regenerate.
name: {kind}-release

on:
  workflow_call:
    inputs:
      release-environment:
        description: Caller environment with deployment protection configured by its owner
        type: string
        default: release
{tool_input}
permissions: {{}}

concurrency:
  group: package-release-${{{{ github.repository }}}}
  cancel-in-progress: false

jobs:
  build:
    if: >-
      (github.event_name == 'push' &&
       github.ref == format('refs/heads/{{0}}', github.event.repository.default_branch) &&
       startsWith(github.event.head_commit.message, 'Release ')) ||
      (github.event_name == 'workflow_dispatch' &&
       (github.ref == format('refs/heads/{{0}}', github.event.repository.default_branch) ||
        startsWith(github.ref, 'refs/tags/v')))
    runs-on: ubuntu-24.04
    timeout-minutes: 30
    permissions:
      contents: read
    outputs:
      version: ${{{{ steps.prepare.outputs.version }}}}
      artifact-id: ${{{{ steps.archive.outputs.artifact-id }}}}
    env:
      KIND: {kind}
      RELEASE_ENVIRONMENT: ${{{{ inputs.release-environment }}}}
    steps:
      - uses: actions/checkout@{CHECKOUT} # v7.0.1
        with:
          persist-credentials: false
          ref: ${{{{ github.sha }}}}
"""
    text += step_script("Validate release and recover an existing artifact", "prepare.py", """        id: prepare
        env:
          GH_TOKEN: ${{ github.token }}
""")
    if kind == "npm":
        text += f"""      - uses: actions/setup-node@{NODE} # v7.1.0
        if: steps.prepare.outputs.restored != 'true'
        with:
          node-version: ${{{{ inputs.node-version }}}}
          package-manager-cache: false
      - name: Build, test and pack once
        if: steps.prepare.outputs.restored != 'true'
        shell: bash
        run: |
          npm ci
          npm run build --if-present
          npm test
          npm pack --ignore-scripts --json > "$RUNNER_TEMP/npm-pack.json"
"""
    elif kind == "rust":
        text += r"""      - name: Build, test and verify the packaged crate
        if: steps.prepare.outputs.restored != 'true'
        shell: bash
        env:
          TOOLCHAIN: ${{ inputs.toolchain }}
        run: |
          [[ "$TOOLCHAIN" =~ ^(stable|beta|nightly|[0-9]+\.[0-9]+\.[0-9]+)(-[0-9]{4}-[0-9]{2}-[0-9]{2})?$ ]] || exit 1
          rustup toolchain install "$TOOLCHAIN" --profile minimal --no-self-update
          cargo "+$TOOLCHAIN" test --locked
          cargo "+$TOOLCHAIN" package --locked
"""
    else:
        text += f"""      - uses: actions/setup-go@{GO} # v7.0.0
        if: steps.prepare.outputs.restored != 'true'
        with:
          go-version-file: go.mod
          cache: false
      - name: Build and test the module
        if: steps.prepare.outputs.restored != 'true'
        shell: bash
        env:
          GOWORK: 'off'
          GOFLAGS: '-mod=readonly'
        run: |
          go test ./...
          go vet ./...
"""
    text += step_script("Seal the release bundle", "bundle.py", "        if: steps.prepare.outputs.restored != 'true'\n")
    text += f"""      - uses: actions/upload-artifact@{UPLOAD} # v7.0.2
        id: archive
        with:
          name: release-{kind}-${{{{ github.run_id }}}}-${{{{ github.run_attempt }}}}
          path: ${{{{ runner.temp }}}}/release-{kind}.zip
          if-no-files-found: error
          retention-days: 30

  publish:
    needs: build
    runs-on: ubuntu-24.04
    timeout-minutes: 20
    environment: ${{{{ inputs.release-environment }}}}
    permissions:
      contents: write
"""
    if kind == "npm":
        text += "      packages: write\n"
    if kind in {"npm", "rust"}:
        text += "      id-token: write\n"
    text += f"""    env:
      KIND: {kind}
      VERSION: ${{{{ needs.build.outputs.version }}}}
    steps:
      - uses: actions/download-artifact@{DOWNLOAD} # v8.0.2
        with:
          artifact-ids: ${{{{ needs.build.outputs.artifact-id }}}}
          merge-multiple: true
          path: ${{{{ runner.temp }}}}/incoming
"""
    if kind == "npm":
        text += f"""      - uses: actions/setup-node@{NODE} # v7.1.0
        with:
          node-version: '24'
          package-manager-cache: false
      - name: Install the verified OIDC-capable npm CLI version
        run: npm install --global npm@11.21.1 --ignore-scripts --registry=https://registry.npmjs.org
"""
    elif kind == "rust":
        text += f"""      - uses: rust-lang/crates-io-auth-action@{AUTH} # v1.0.6
        id: auth
"""
    else:
        text += f"""      - uses: actions/setup-go@{GO} # v7.0.0
        with:
          go-version: stable
          cache: false
"""
    env = "        env:\n          GH_TOKEN: ${{ github.token }}\n"
    if kind == "rust":
        env += "          CARGO_REGISTRY_TOKEN: ${{ steps.auth.outputs.token }}\n"
    text += step_script("Publish verified artifacts in order", "publish.py", env)
    return text


if __name__ == "__main__":
    check = "--check" in sys.argv
    failed = False
    for ecosystem in ("go", "npm", "rust"):
        path = WORKFLOWS / (ecosystem + "-release.yml")
        content = render(ecosystem)
        if check:
            if not path.exists() or path.read_text() != content:
                print("Generated workflow is stale:", path)
                failed = True
        else:
            path.write_text(content)
    sys.exit(1 if failed else 0)
